const API = '/api/v1';
const ROLE_HOME = {PRODUCT_ADMIN:'/admin/login', SELLER:'/seller/login', CUSTOMER:'/customer/login'};
const ROLE_DASH = {PRODUCT_ADMIN:'/admin/dashboard', SELLER:'/seller/dashboard', CUSTOMER:'/customer/dashboard'};
const state = {
  role:null,user:null,categories:[],coupons:[],products:[],filteredProducts:[],cart:null,cartCoupons:[],orders:[],
  seller:{profile:null,products:[],warehouses:[],inventory:[],orders:[],productTab:'ALL',orderTab:'ALL'},
  admin:{selectedCategoryId:null,couponFilter:'ALL'},
  public:{selectedCategoryId:null,query:'',sortBy:'name',direction:'ASC',attrFilters:{}}
};

function byId(id){return document.getElementById(id)}
function tokenKey(role){return `vincommerce.${role}.jwt`}
function userKey(role){return `vincommerce.${role}.user`}
function getToken(role='CUSTOMER'){return localStorage.getItem(tokenKey(role))}
function setToken(role,token){localStorage.setItem(tokenKey(role),token)}
function decodeJwt(token){try{let p=token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');p+='='.repeat((4-p.length%4)%4);return JSON.parse(atob(p))}catch(e){return null}}
function hydrateUser(role){const token=getToken(role);if(!token)return null;const stored=localStorage.getItem(userKey(role));if(stored){try{const parsed=JSON.parse(stored);if(parsed.expiresAt&&new Date(parsed.expiresAt)<new Date()){localStorage.removeItem(tokenKey(role));localStorage.removeItem(userKey(role));return null}return{email:parsed.email||role.toLowerCase(),role,userId:parsed.userId,exp:parsed.expiresAt}}catch(e){}}const c=decodeJwt(token)||{};if(c.exp&&c.exp*1000<Date.now()){localStorage.removeItem(tokenKey(role));localStorage.removeItem(userKey(role));return null}const user={email:c.email||role.toLowerCase(),role,userId:c.sub,exp:c.exp};localStorage.setItem(userKey(role),JSON.stringify(user));return user}
function pageContent(data){return Array.isArray(data)?data:(data?.content||[])}
function money(v){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Math.max(0,Number(v||0)))}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmtDate(v){return v?new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'-'}
function localValue(iso){if(!iso)return'';const d=new Date(iso);const off=d.getTimezoneOffset();return new Date(d.getTime()-off*60000).toISOString().slice(0,16)}
function toIso(local){return local?new Date(local).toISOString():null}
function toast(msg,type='info'){const t=byId('toast');if(!t){console.log(msg);return}t.textContent=msg;t.className=`toast ${type}`;t.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.add('hidden'),3600)}
function badge(v){const s=String(v||'UNKNOWN');let tone='neutral';if(['ACTIVE','LIVE','PUBLISHED','IN_STOCK','PLACED','PAID','SHIPPED','COMPLETED'].includes(s))tone='success';if(['DRAFT','SCHEDULED','PENDING','UNPUBLISHED','INSUFFICIENT_STOCK','RESERVED'].includes(s))tone='warning';if(['EXPIRED','DELETED','CANCELLED','OUT_OF_STOCK','FAILED','INACTIVE'].includes(s))tone='danger';return `<span class="badge ${tone}">${esc(s)}</span>`}
function productIcon(category){const c=(category||'').toLowerCase();if(c.includes('phone'))return'📱';if(c.includes('laptop'))return'💻';if(c.includes('camera'))return'📷';if(c.includes('access'))return'🎧';if(c.includes('men')||c.includes('women')||c.includes('apparel'))return'👕';return'📦'}
function openModal(id){byId(id)?.classList.add('open')}
function closeModal(id){byId(id)?.classList.remove('open')}
function openDrawer(id){byId(id)?.classList.add('open');byId('drawer-backdrop')?.classList.add('open')}
function closeDrawer(id){byId(id)?.classList.remove('open');byId('drawer-backdrop')?.classList.remove('open')}
document.addEventListener('click',function(e){const drawer=byId('cart-drawer');if(!drawer||!drawer.classList.contains('open'))return;if(drawer.contains(e.target))return;if(e.target.closest('.cart-btn')||e.target.closest('[onclick*="openCustomerCart"]')||e.target.closest('[onclick*="addToCart"]'))return;closeDrawer('cart-drawer')})
function scrollToSection(id){byId(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function empty(title,text=''){return `<div class="empty-state"><strong>${esc(title)}</strong><span>${esc(text)}</span></div>`}

async function api(path,{method='GET',body=null,role=state.role,auth=true}={}){
  const headers={'Content-Type':'application/json'};
  if(auth){const token=getToken(role);if(token)headers.Authorization=`Bearer ${token}`}
  const res=await fetch(path,{method,headers,body:body==null?null:JSON.stringify(body)});
  if(res.status===401&&auth){if(role)localStorage.removeItem(tokenKey(role));throw new Error('Session expired. Please login again.');}
  const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch(e){data=text}
  if(!res.ok){throw new Error(data?.message||data?.error||`Request failed with ${res.status}`)}
  return data;
}
const get=(p,o={})=>api(p,{...o,method:'GET'});const post=(p,b,o={})=>api(p,{...o,method:'POST',body:b});const put=(p,b,o={})=>api(p,{...o,method:'PUT',body:b});const patch=(p,b={},o={})=>api(p,{...o,method:'PATCH',body:b});const del=(p,o={})=>api(p,{...o,method:'DELETE'});

async function loadCategories(){state.categories=await get(`${API}/categories/tree`,{auth:false});return state.categories}
async function loadCoupons(){state.coupons=pageContent(await get(`${API}/coupons?page=0&size=200`,{auth:false}));return state.coupons}
async function loadProducts(){const sort=byId('public-sort')?.value||'name|ASC';const [sortBy,direction]=sort.split('|');state.public.query=byId('public-search')?.value?.trim()||'';state.public.sortBy=sortBy;state.public.direction=direction||'ASC';const params=new URLSearchParams({page:'0',size:'80',sortBy:state.public.sortBy,direction:state.public.direction});if(state.public.query)params.set('q',state.public.query);if(state.public.selectedCategoryId)params.set('categoryId',state.public.selectedCategoryId);collectVisibleAttributeFilters().forEach(([code,value])=>params.set(`attr_${code}`,value));state.products=pageContent(await get(`${API}/search/products?${params}`,{auth:false}));state.filteredProducts=[...state.products];return state.products}
function collectVisibleAttributeFilters(){const filters=[...document.querySelectorAll('[data-public-attr-filter]')].map(el=>[el.dataset.publicAttrFilter,el.value?.trim()]).filter(([code,value])=>code&&value);state.public.attrFilters=Object.fromEntries(filters);return filters}
function categoryById(id){return state.categories.find(c=>c.id===id)}
function childrenOf(id){return state.categories.filter(c=>(c.parentId||'')===(id||''))}
function roots(){return childrenOf(null)}
function isLeaf(id){return childrenOf(id).length===0}
function ancestorsOf(id){const ids=[];let c=categoryById(id);while(c){ids.push(c.id);c=categoryById(c.parentId)}return ids}
function categoryPath(id){const c=categoryById(id);if(!c)return id||'-';return c.parentId?`${categoryPath(c.parentId)} › ${c.name}`:c.name}
function lifecycle(c){const now=Date.now();if(c.status&&c.status!=='ACTIVE')return'INACTIVE';if(new Date(c.startsAt).getTime()>now)return'SCHEDULED';if(new Date(c.endsAt).getTime()<now)return'EXPIRED';return'LIVE'}
function couponAppliesToProduct(coupon, product){if(lifecycle(coupon)!=='LIVE')return false;if(!coupon.enrolledProductIds?.includes(product.productId))return false;const eligible=coupon.eligibleCategoryIds||[];if(!eligible.length)return true;return ancestorsOf(product.categoryId).some(id=>eligible.includes(id))}
function couponText(c){return c.discountType==='FLAT'?`${money(c.value)} off`:`${Number(c.value)}% off up to ${money(c.maxDiscountAmount)}`}
function productOffers(product){return state.coupons.filter(c=>couponAppliesToProduct(c,product))}

async function initStorefront(){state.role='CUSTOMER';state.user=hydrateUser('CUSTOMER');updateCustomerEntry();try{await Promise.all([loadCategories(),loadCoupons(),loadProducts()]);renderPublicHome();if(state.user)await safeRefreshCartBadge()}catch(e){toast(e.message,'error')}}
function updateCustomerEntry(){const link=byId('customer-entry-link');if(!link)return;if(state.user){link.textContent='My Account';link.href='/customer/dashboard'}else{link.textContent='Login';link.href='/customer/login'}}
async function safeRefreshCartBadge(){try{state.cart=await get(`${API}/cart`,{role:'CUSTOMER'});setCartCount(state.cart?.items?.length||0)}catch(e){setCartCount(0)}}
function setCartCount(n){['public-cart-count'].forEach(id=>{if(byId(id))byId(id).textContent=n})}
function renderPublicHome(){renderHeroOffers();renderCategoryStrip();renderPublicCategoryTree();renderPublicAttributeFilters();renderCouponStrip();renderPublicCatalog()}
function renderHeroOffers(){const h=byId('hero-offer-list');if(!h)return;const live=state.coupons.filter(c=>lifecycle(c)==='LIVE').slice(0,3);h.innerHTML=live.length?live.map(c=>`<div class="offer-pill"><div><strong>${esc(c.code)}</strong><div class="small muted">${esc(c.description||couponText(c))}</div></div>${badge('LIVE')}</div>`).join(''):empty('No live offers','Product Admin can create coupons.');}
function renderCategoryStrip(){const h=byId('public-category-strip');if(!h)return;h.innerHTML=roots().map(c=>`<button class="category-tile" onclick="selectPublicCategory('${c.id}')"><strong>${esc(c.name)}</strong><span class="muted small">${childrenOf(c.id).length} classifications</span></button>`).join('')}
function renderCouponStrip(){const h=byId('public-coupon-strip');if(!h)return;h.innerHTML=state.coupons.slice(0,6).map(c=>`<article class="coupon-tile"><strong>${esc(c.code)}</strong><p class="small muted">${esc(c.description||couponText(c))}</p><div class="inline-actions">${badge(lifecycle(c))}<span class="chip">${esc(c.discountType)}</span></div></article>`).join('')||empty('No coupons configured','Product Admin can create coupons.');}
function renderPublicCategoryTree(){const h=byId('public-category-tree');if(!h)return;h.innerHTML=roots().map(root=>`<div class="tree-node"><button class="tree-main ${state.public.selectedCategoryId===root.id?'active':''}" onclick="selectPublicCategory('${root.id}')"><span>${esc(root.name)}</span><span>${childrenOf(root.id).length}</span></button><div class="tree-children">${childrenOf(root.id).map(child=>`<button class="tree-child ${state.public.selectedCategoryId===child.id?'active':''}" onclick="selectPublicCategory('${child.id}')">${esc(child.name)}</button>`).join('')}</div></div>`).join('')}
function renderPublicAttributeFilters(){const h=byId('public-attribute-filters');if(!h)return;const selected=categoryById(state.public.selectedCategoryId);if(!selected){h.innerHTML='<p class="small muted">Select a category to see matching filters.</p>';return}if(!isLeaf(selected.id)){h.innerHTML='<p class="small muted">Select a final sub-category to filter by attributes.</p>';return}const attrs=(selected.attributes||[]).filter(a=>a.searchable&&a.visibleToCustomer);h.innerHTML=attrs.length?attrs.map(a=>{const current=state.public.attrFilters?.[a.code]||'';const values=(a.allowedValues||'').split(',').map(v=>v.trim()).filter(Boolean);const control=values.length?`<select data-public-attr-filter="${esc(a.code)}" onchange="searchPublicCatalog()"><option value="">Any</option>${values.map(v=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input data-public-attr-filter="${esc(a.code)}" value="${esc(current)}" placeholder="Any ${esc(a.labelText||a.name)}" onkeydown="if(event.key==='Enter') searchPublicCatalog()">`;return `<div class="form-field compact-field"><label>${esc(a.labelText||a.name)}</label>${control}</div>`}).join(''):'<p class="small muted">No customer-visible filters for this category.</p>'}
async function selectPublicCategory(id){state.public.selectedCategoryId=id;state.public.attrFilters={};renderPublicCategoryTree();renderPublicAttributeFilters();try{await loadProducts();renderPublicCatalog()}catch(e){toast(e.message,'error')}}
async function clearPublicFilters(){state.public.selectedCategoryId=null;state.public.attrFilters={};if(byId('public-search'))byId('public-search').value='';if(byId('public-instock-only'))byId('public-instock-only').checked=false;renderPublicAttributeFilters();await searchPublicCatalog()}
async function searchPublicCatalog(){try{await loadProducts();renderPublicCategoryTree();renderPublicAttributeFilters();renderPublicCatalog()}catch(e){toast(e.message,'error')}}
function renderPublicCatalog(){const h=byId('public-product-grid');if(!h)return;let rows=[...(state.products||[])];if(byId('public-instock-only')?.checked)rows=rows.filter(p=>Number(p.totalAvailableQuantity)>0);const title=byId('public-result-subtitle');if(title)title.textContent=`${rows.length} products ${state.public.selectedCategoryId?'in '+categoryPath(state.public.selectedCategoryId):'available in catalog'}`;h.innerHTML=rows.length?rows.map(renderProductCard).join(''):empty('No products found','Try another search or category.');}
function renderProductCard(p){const offers=productOffers(p);return `<article class="market-card"><div class="product-visual">${offers[0]?`<span class="offer-badge">${esc(offers[0].code)}</span>`:''}${productIcon(p.categoryName)}</div><div class="product-body"><div><div class="product-title">${esc(p.name)}</div><div class="product-meta">${esc(categoryPath(p.categoryId))} · ${esc(p.sku)}</div></div><div class="price-row"><span class="price">${money(p.price)}</span>${Number(p.totalAvailableQuantity)>0?badge('IN_STOCK'):badge('OUT_OF_STOCK')}</div><p class="small muted">${esc(p.description||'')}</p><div class="chip-row">${Object.entries(p.attributes||{}).slice(0,4).map(([k,v])=>`<span class="chip">${esc(k)}: ${esc(v)}</span>`).join('')}</div>${offers.length?`<div class="chip-row">${offers.slice(0,2).map(o=>`<span class="chip">🏷 ${esc(o.code)}</span>`).join('')}</div>`:''}<div class="card-actions"><button class="btn-primary btn-sm" onclick="addToCartFromPublic('${p.productId}')" ${p.totalAvailableQuantity<=0?'disabled':''}>Add to cart</button><button class="btn-ghost btn-sm" onclick="showProductDetails('${p.productId}')">View details</button></div></div></article>`}
async function showProductDetails(id){try{const [p,offers]=await Promise.all([get(`${API}/products/${id}`,{auth:false}),get(`${API}/coupons/products/${id}/eligible`,{auth:false})]);const visibleAttrs=(p.attributes||[]).filter(a=>a.visibleToCustomer!==false);byId('product-modal-body').innerHTML=`<div class="product-detail-grid"><div class="product-detail-art">${productIcon(p.categoryName)}</div><div><div class="eyebrow">${esc(p.categoryName)}</div><h1 style="font-size:2.5rem;letter-spacing:-.07em;margin:10px 0">${esc(p.name)}</h1><p class="muted">${esc(p.description||'')}</p><div class="price" style="font-size:2rem">${money(p.price)}</div><div class="chip-row" style="margin:14px 0">${visibleAttrs.map(a=>`<span class="chip">${esc(a.labelText||a.name||a.code)}: ${esc(a.value)}</span>`).join('')}</div><h3>🏷 Available offers</h3><div class="offer-stack">${offers.length?offers.map(o=>{const couponData=state.coupons.find(c=>c.code===o.code);const catNames=(couponData?.eligibleCategoryIds||[]).map(cid=>{const cat=categoryById(cid);return cat?cat.name:null}).filter(Boolean);return `<div class="offer-card"><div><strong>${esc(o.code)}</strong><div class="small muted">${esc(o.description||couponText(o))}</div>${catNames.length?`<div class="small muted">📁 Applies to: ${catNames.map(n=>esc(n)).join(', ')}</div>`:''}<div class="small muted">Valid till ${fmtDate(o.endsAt)}</div></div><div style="text-align:right"><strong style="color:var(--success)">${money(o.estimatedDiscount)}</strong><div class="small muted">est. save</div></div></div>`}).join(''):empty('No offers for this product','Coupons appear when Product Admin creates them and seller enrolls the product.')}</div><button class="btn-primary btn-full" style="margin-top:18px" onclick="addToCartFromPublic('${p.id}')">Add to cart</button></div></div>`;openModal('product-modal')}catch(e){toast(e.message,'error')}}
function requireCustomer(message='Login to continue.'){state.user=hydrateUser('CUSTOMER');if(state.user)return true;byId('login-required-message')&&(byId('login-required-message').textContent=message);openModal('login-required-modal');return false}
async function addToCartFromPublic(productId){if(!requireCustomer('Please login to add this product to your cart.'))return;try{state.role='CUSTOMER';await post(`${API}/cart/items`,{productId,quantity:1},{role:'CUSTOMER'});toast('Added to cart','success');await openCustomerCart()}catch(e){toast(e.message,'error')}}
async function openCustomerCart(){if(!requireCustomer('Please login to view and manage your cart.'))return;try{state.role='CUSTOMER';state.cart=await get(`${API}/cart`,{role:'CUSTOMER'});state.cartCoupons=await get(`${API}/cart/eligible-coupons`,{role:'CUSTOMER'});renderCart();openDrawer('cart-drawer')}catch(e){toast(e.message,'error')}}
function openDrawer(id){byId(id)?.classList.add('open')}
function renderCart(){const c=state.cart;setCartCount(c?.items?.length||0);const body=byId('cart-body');if(!body)return;if(!c||!c.items?.length){body.innerHTML=empty('Your cart is empty','Add products from the catalog.');byId('cart-coupons').innerHTML='';byId('cart-summary').innerHTML='';return}body.innerHTML=c.items.map(i=>{const lineTotal=Math.max(0,Number(i.totalAmount||0));const lineDiscount=Math.max(0,Number(i.discountAmount||0));return `<div class="cart-line"><div class="cart-thumb">${productIcon(i.productName)}</div><div><strong>${esc(i.productName)}</strong><div class="small muted">${money(i.unitPrice)} × ${i.quantity} · ${badge(i.stockStatus)}</div><div class="qty-control"><input id="qty-${i.productId}" type="number" min="0" value="${i.quantity}"><button class="btn-ghost btn-sm" onclick="updateCartQuantity('${i.productId}')">✓</button><button class="btn-danger btn-sm" onclick="removeCartItem('${i.productId}')">✕</button></div></div><div style="text-align:right;white-space:nowrap"><strong>${money(lineTotal)}</strong>${lineDiscount>0?`<div class="small muted" style="color:var(--success)">-${money(lineDiscount)}</div>`:''}</div></div>`}).join('');renderCartCoupons();const cartTotal=Math.max(0,Number(c.totalAmount||0));const cartDiscount=Math.max(0,Number(c.discountAmount||0));byId('cart-summary').innerHTML=`<div class="summary-card"><div class="summary-row"><span>Subtotal</span><strong>${money(c.subtotal)}</strong></div>${cartDiscount>0?`<div class="summary-row"><span>Discount ${c.couponCode?'('+esc(c.couponCode)+')':''}</span><strong style="color:var(--success)">-${money(cartDiscount)}</strong></div>`:''}${c.couponCode&&cartDiscount===0?`<div class="summary-row"><span class="small muted" style="color:var(--warning)">⚠️ Coupon "${esc(c.couponCode)}" is not providing a discount. It may have expired or does not apply to your items.</span></div>`:''}<div class="summary-row total"><span>Total</span><strong>${money(cartTotal)}</strong></div><div class="form-field" style="margin-top:14px"><label>Shipping address</label><textarea id="shipping-address" placeholder="House, street, city, PIN" style="min-height:60px"></textarea></div><button class="btn-success btn-full" onclick="placeOrderFromCart()" ${c.checkoutReady?'':'disabled'}>Place order</button>${c.checkoutReady?'':'<div class="alert error" style="font-size:.82rem">Some items are out of stock.</div>'}</div>`}
function renderCartCoupons(){const h=byId('cart-coupons');if(!h)return;const applied=state.cart?.couponCode;const cartDiscount=Math.max(0,Number(state.cart?.discountAmount||0));let html='<div class="coupon-picker-section">';if(applied){if(cartDiscount>0){html+=`<div class="coupon-applied-banner"><span>🎉</span><span class="applied-text">Coupon ${esc(applied)} applied! Saving ${money(cartDiscount)}</span><button onclick="removeCartCoupon()">Remove</button></div>`}else{html+=`<div class="coupon-applied-banner" style="background:#fef3c7;border-color:#fcd34d;"><span>⚠️</span><span class="applied-text" style="color:#92400e;">Coupon "${esc(applied)}" is not giving a discount. It may have expired or doesn't apply to current items.</span><button onclick="removeCartCoupon()">Remove</button></div>`}}html+='<h3>🏷 Available Coupons</h3>';if(state.cartCoupons?.length){html+=state.cartCoupons.map(o=>{const couponData=state.coupons.find(c=>c.code===o.code);const catNames=(couponData?.eligibleCategoryIds||[]).map(id=>{const cat=categoryById(id);return cat?cat.name:null}).filter(Boolean);const catLabel=catNames.length?catNames.join(', '):'All categories';const isEligible=o.eligible!==false;return `<div class="coupon-pick-card${isEligible?'':' coupon-pick-locked'}"><div class="pick-icon">${isEligible?'🏷':'🔒'}</div><div class="pick-info"><div class="pick-code">${esc(o.code)}</div><div class="pick-desc">${esc(o.description||couponText(o))}</div><div class="small muted" style="margin-top:2px">📁 ${esc(catLabel)}</div>${isEligible?`<div class="pick-savings">Save ${money(o.estimatedDiscount)}</div>`:`<div class="pick-reason">${esc(o.reason||'Min cart ₹'+Number(o.minCartAmount||0).toLocaleString('en-IN')+' required')}</div>`}</div><div class="pick-action"><button class="btn-primary btn-sm" onclick="applyCartCoupon('${esc(o.code)}')" ${applied||!isEligible?'disabled':''}>Apply</button></div></div>`}).join('')}else{html+='<p class="small muted" style="padding:8px 0">No coupons available for your current cart items.</p>'}html+='</div>';h.innerHTML=html}
async function updateCartQuantity(productId){try{await put(`${API}/cart/items/${productId}`,{quantity:Number(byId(`qty-${productId}`).value||0)},{role:'CUSTOMER'});toast('Cart updated','success');await openCustomerCart()}catch(e){toast(e.message,'error')}}
async function removeCartItem(productId){try{await del(`${API}/cart/items/${productId}`,{role:'CUSTOMER'});toast('Item removed','success');await openCustomerCart()}catch(e){toast(e.message,'error')}}
async function applyCartCoupon(code){try{await post(`${API}/cart/coupon`,{code},{role:'CUSTOMER'});toast(`Coupon ${code} applied`,'success');await openCustomerCart()}catch(e){toast(e.message,'error')}}
async function removeCartCoupon(){try{await del(`${API}/cart/coupon`,{role:'CUSTOMER'});toast('Coupon removed','success');await openCustomerCart()}catch(e){toast(e.message,'error')}}
async function placeOrderFromCart(){try{const order=await post(`${API}/orders`,{shippingAddress:byId('shipping-address')?.value?.trim()||'Demo shipping address'},{role:'CUSTOMER'});toast(`Order ${order.orderNumber} placed`,'success');closeDrawer('cart-drawer');await safeRefreshCartBadge();if(document.body.dataset.page==='customer'){await loadAndRenderCustomerOrders();showCustomerSection('orders-section')}}catch(e){toast(e.message,'error')}}

async function initCustomerWorkspace(){state.role='CUSTOMER';state.user=hydrateUser('CUSTOMER');if(!state.user){location.replace('/customer/login');return}try{await Promise.all([loadCategories(),loadCoupons(),loadProducts(),safeRefreshCartBadge(),loadAndRenderCustomerOrders()]);renderPublicCategoryTree();renderPublicAttributeFilters();renderPublicCatalog();renderCustomerCoupons();renderCustomerAccount()}catch(e){toast(e.message,'error')}}
function showCustomerSection(id){document.querySelectorAll('.customer-section').forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('.storefront-nav [data-customer-section]').forEach(b=>b.classList.toggle('active',b.dataset.customerSection===id));if(id==='deals-section')renderCustomerCoupons()}
async function loadAndRenderCustomerOrders(){try{state.orders=pageContent(await get(`${API}/orders?page=0&size=50`,{role:'CUSTOMER'}));const h=byId('customer-orders-table');if(!h)return;if(!state.orders.length){h.innerHTML=empty('No orders yet','Place your first order from the cart.');return}h.innerHTML=`<div class="order-cards">${state.orders.map(o=>`<article class="order-card-item"><div class="order-header-row"><div><span class="order-number">#${esc(o.orderNumber)}</span><span class="order-date"> · ${fmtDate(o.createdAt)}</span></div><div>${badge(o.status)} ${badge(o.paymentStatus)}</div></div><div class="order-lines">${(o.lines||[]).map(l=>`<div class="order-line"><div class="order-line-icon">${productIcon(l.productName)}</div><div class="order-line-info"><strong>${esc(l.productName)}</strong><div class="line-meta">Qty: ${l.quantity} × ${money(l.unitPrice)} ${badge(l.fulfillmentStatus)}</div></div><div style="text-align:right;font-weight:800">${money(l.totalAmount)}</div></div>`).join('')}</div><div class="order-footer"><div><span class="order-total">${money(o.totalAmount)}</span>${o.discountAmount>0?`<span class="small muted" style="margin-left:8px">Saved ${money(o.discountAmount)}</span>`:''}</div><div class="order-address">📍 ${esc(o.shippingAddress||'—')}</div></div></article>`).join('')}</div>`}catch(e){toast(e.message,'error')}}
function renderCustomerAccount(){const h=byId('customer-account-card');if(!h)return;h.innerHTML=`<article class="info-panel"><h2>👤 My Account</h2><p><strong>${esc(state.user.email)}</strong></p><p class="muted">Role: CUSTOMER<br>User ID: <span class="kbd">${esc(state.user.userId)}</span></p><div style="margin-top:18px"><button class="btn-danger btn-sm" onclick="logoutRole('CUSTOMER')">Sign out</button></div></article>`}
function renderCustomerCoupons(){const h=byId('customer-coupon-tickets');if(!h)return;if(!state.coupons.length){h.innerHTML=empty('No coupons available','Check back later for exciting deals!');return}h.innerHTML=state.coupons.map(c=>{const status=lifecycle(c);const isExpired=status==='EXPIRED'||status==='INACTIVE';const discountDisplay=c.discountType==='FLAT'?`<div class="discount-value">${money(c.value)}</div><div class="discount-label">FLAT OFF</div>`:`<div class="discount-value">${Number(c.value)}%</div><div class="discount-label">UP TO ${money(c.maxDiscountAmount)}</div>`;const catNames=(c.eligibleCategoryIds||[]).map(id=>{const cat=categoryById(id);return cat?cat.name:null}).filter(Boolean);const categoryHtml=catNames.length?`<div class="ticket-categories"><span class="small" style="font-weight:800;color:#334155">Applicable on:</span> <span class="small muted">${catNames.map(n=>`<span class="chip">${esc(n)}</span>`).join(' ')}</span></div>`:`<div class="ticket-categories"><span class="chip" style="background:#dcfce7;color:#166534;border-color:#86efac">All categories</span></div>`;return `<div class="coupon-ticket ${isExpired?'expired':''}"><div class="ticket-left">${discountDisplay}</div><div class="ticket-right"><div class="ticket-code">${esc(c.code)}</div><div class="ticket-desc">${esc(c.description||couponText(c))}</div>${categoryHtml}<div class="ticket-meta">${badge(status)}${c.minCartAmount>0?`<span class="chip">Min cart ${money(c.minCartAmount)}</span>`:''}</div>${!isExpired?`<div class="ticket-meta"><span class="small muted">Valid till ${fmtDate(c.endsAt)}</span></div>`:''}</div></div>`}).join('')}

function initConsole(role){state.role=role;state.user=hydrateUser(role);if(!state.user){location.replace(ROLE_HOME[role]);return}document.querySelectorAll('[data-section]').forEach(b=>b.addEventListener('click',()=>showConsoleSection(b.dataset.section)));}
function showConsoleSection(id){document.querySelectorAll('.console-section').forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===id));const titles={
 'admin-overview':'Overview','admin-categories':'Categories & Attributes','admin-coupons':'Coupons','seller-overview':'Overview','seller-profile':'Profile','seller-products':'Products','seller-new-product':'New Product','seller-promotions':'Promotions','seller-warehouses':'Warehouses','seller-inventory':'Inventory','seller-orders':'Orders'};if(byId('console-title'))byId('console-title').textContent=titles[id]||'Workspace';if(byId('seller-title'))byId('seller-title').textContent=titles[id]||'Workspace'}
async function logoutRole(role){try{state.role=role;await api(`${API}/auth/logout`,{method:'POST',role})}catch(e){}localStorage.removeItem(tokenKey(role));localStorage.removeItem(userKey(role));location.assign(ROLE_HOME[role]||'/')}

async function initAdminConsole(){initConsole('PRODUCT_ADMIN');byId('admin-email')&&(byId('admin-email').textContent=state.user.email);await refreshAdminConsole()}
async function refreshAdminConsole(){try{await Promise.all([loadCategories(),loadCoupons()]);renderAdminStats();renderAdminCategoryTree();renderAdminCouponList();renderAdminSelects()}catch(e){toast(e.message,'error')}}
function renderAdminStats(){byId('admin-stat-categories').textContent=state.categories.length;byId('admin-stat-leaves').textContent=state.categories.filter(c=>isLeaf(c.id)).length;byId('admin-stat-attributes').textContent=state.categories.reduce((s,c)=>s+(c.attributes?.length||0),0);byId('admin-stat-coupons').textContent=state.coupons.length;
const leaves=state.categories.filter(c=>isLeaf(c.id)).length;const parents=state.categories.length-leaves;const attrs=state.categories.reduce((s,c)=>s+(c.attributes?.length||0),0);
if(byId('admin-cat-total'))byId('admin-cat-total').textContent=state.categories.length;if(byId('admin-cat-leaves'))byId('admin-cat-leaves').textContent=leaves;if(byId('admin-cat-parents'))byId('admin-cat-parents').textContent=parents;if(byId('admin-cat-attrs'))byId('admin-cat-attrs').textContent=attrs;if(byId('admin-cat-tree-count'))byId('admin-cat-tree-count').textContent=state.categories.length;
const live=state.coupons.filter(c=>lifecycle(c)==='LIVE').length;const scheduled=state.coupons.filter(c=>lifecycle(c)==='SCHEDULED').length;const expired=state.coupons.filter(c=>lifecycle(c)==='EXPIRED'||lifecycle(c)==='INACTIVE').length;
if(byId('admin-coupon-stat-live'))byId('admin-coupon-stat-live').textContent=live;if(byId('admin-coupon-stat-scheduled'))byId('admin-coupon-stat-scheduled').textContent=scheduled;if(byId('admin-coupon-stat-expired'))byId('admin-coupon-stat-expired').textContent=expired;if(byId('admin-coupon-stat-total'))byId('admin-coupon-stat-total').textContent=state.coupons.length}
function renderAdminSelects(){const sel=byId('admin-category-parent');if(sel)sel.innerHTML='<option value="">Root category</option>'+state.categories.map(c=>`<option value="${c.id}">${esc(categoryPath(c.id))}</option>`).join('');renderCouponCategoryChecks()}
function toggleCategoryExpand(id,e){e.stopPropagation();if(!state.admin.expandedCategories)state.admin.expandedCategories={};state.admin.expandedCategories[id]=!state.admin.expandedCategories[id];renderAdminCategoryTree()}
function renderAdminCategoryTree(){const h=byId('admin-category-tree');if(!h)return;if(!state.admin.expandedCategories)state.admin.expandedCategories={};const renderNode=(c)=>{const leaf=isLeaf(c.id);const childCount=childrenOf(c.id).length;const attrCount=c.attributes?.length||0;const expanded=!!state.admin.expandedCategories[c.id];return `<div class="admin-node${expanded?' expanded':''}"><button class="admin-node-head ${state.admin.selectedCategoryId===c.id?'active':''}" onclick="selectAdminCategory('${c.id}')">${childCount?`<span class="node-chevron${expanded?' rotated':''}" onclick="toggleCategoryExpand('${c.id}',event)">▶</span>`:''}<span class="node-icon ${leaf?'leaf-icon':'parent-icon'}">${leaf?'🍃':'📂'}</span><div class="node-info"><span class="node-name">${esc(c.name)}</span><span class="node-path">${leaf?esc(categoryPath(c.id)):(childCount+' sub-categor'+(childCount===1?'y':'ies'))}</span></div><div class="node-badges">${attrCount?`<span class="node-attr-count">🔧 ${attrCount}</span>`:''} ${leaf?badge('LEAF'):badge('PARENT')}</div></button>${childCount?`<div class="admin-children${expanded?'':' collapsed'}">${childrenOf(c.id).map(renderNode).join('')}</div>`:''}</div>`};h.innerHTML=roots().map(renderNode).join('')||empty('No categories','Create your first root category.');if(state.admin.selectedCategoryId)renderAdminCategoryDetail()}
function selectAdminCategory(id){state.admin.selectedCategoryId=id;if(!state.admin.expandedCategories)state.admin.expandedCategories={};if(!isLeaf(id))state.admin.expandedCategories[id]=true;renderAdminCategoryTree();renderAdminCategoryDetail()}
function renderAdminCategoryDetail(){const h=byId('admin-category-detail');const c=categoryById(state.admin.selectedCategoryId);if(!h||!c)return;const leaf=isLeaf(c.id);const mandatory=(c.attributes||[]).filter(a=>a.required);const optional=(c.attributes||[]).filter(a=>!a.required);h.innerHTML=`<div class="admin-cat-detail-header"><div class="detail-breadcrumb">📁 ${esc(categoryPath(c.id))}</div><div class="detail-title-row"><h2>${leaf?'🍃':'📂'} ${esc(c.name)}</h2><div class="detail-actions"><button class="btn-ghost btn-sm" onclick="openCategoryModal('${c.id}')">✏️ Edit</button>${leaf?`<button class="btn-primary btn-sm" onclick="openAttributeModal('${c.id}')">🔧 Add attribute</button>`:''}</div></div></div><div class="admin-cat-detail-body">${leaf?`<div class="attr-section"><div class="attr-section-header"><h3>⚡ Mandatory attributes</h3><span class="attr-count-badge">${mandatory.length}</span></div><div class="attribute-list">${mandatory.map(renderAttributeCard).join('')||'<p class="muted small" style="padding:8px 0;">No mandatory attributes defined.</p>'}</div></div><div class="attr-section"><div class="attr-section-header"><h3>📎 Optional attributes</h3><span class="attr-count-badge">${optional.length}</span></div><div class="attribute-list">${optional.map(renderAttributeCard).join('')||'<p class="muted small" style="padding:8px 0;">No optional attributes defined.</p>'}</div></div>`:`<div class="admin-cat-parent-hint"><span class="parent-hint-icon">📂</span><strong>Parent category</strong><span class="small muted" style="max-width:300px;">Attributes can only be configured on leaf categories (categories with no children). Select or create a sub-category to manage attributes.</span><button class="btn-secondary" style="margin-top:16px" onclick="openCategoryModal(null,'${c.id}')">➕ Add sub-category</button></div>`}</div>`}
function renderAttributeCard(a){const typeIcons={STRING:'Aa',NUMBER:'#',DECIMAL:'#.',BOOLEAN:'⊘',SELECT:'☰',MULTI_SELECT:'☷'};const icon=typeIcons[a.attributeType]||'?';const typeLower=(a.attributeType||'string').toLowerCase();return `<div class="attribute-card"><div class="attr-type-icon type-${typeLower}">${icon}</div><div class="attr-card-body"><div class="attr-card-name">${esc(a.labelText||a.name)}</div><div class="small muted" style="margin-bottom:2px;">${esc(a.code)} · ${a.attributeType}</div>${a.allowedValues?`<div class="chip-row" style="margin-top:4px;">${a.allowedValues.split(',').map(v=>`<span class="chip">${esc(v.trim())}</span>`).join('')}</div>`:''}<div class="attr-card-meta">${a.required?'<span class="attr-meta-tag required-tag">Required</span>':'<span class="attr-meta-tag">Optional</span>'}${a.visibleToCustomer?'<span class="attr-meta-tag visible-tag">👁 Customer visible</span>':'<span class="attr-meta-tag internal-tag">🔒 Internal</span>'}</div></div></div>`}
function openCategoryModal(id=null,parentId=null){const c=id?categoryById(id):null;byId('category-modal-title').textContent=c?'Edit category':'Create category';byId('admin-edit-category-id').value=c?.id||'';byId('admin-category-name').value=c?.name||'';renderAdminSelects();byId('admin-category-parent').value=c?.parentId||parentId||'';openModal('category-modal')}
async function saveCategoryFromModal(){try{const id=byId('admin-edit-category-id').value;const body={name:byId('admin-category-name').value.trim(),parentId:byId('admin-category-parent').value||null,active:true,attributes:null};if(id)await put(`${API}/categories/${id}`,body,{role:'PRODUCT_ADMIN'});else await post(`${API}/categories`,{name:body.name,parentId:body.parentId,attributes:[]},{role:'PRODUCT_ADMIN'});toast('Category saved','success');closeModal('category-modal');await refreshAdminConsole()}catch(e){toast(e.message,'error')}}
function openAttributeModal(categoryId){byId('attribute-category-id').value=categoryId;['attr-code','attr-label','attr-values','attr-min','attr-max'].forEach(id=>byId(id).value='');byId('attr-required').checked=false;byId('attr-visible').checked=true;byId('attr-type').value='STRING';renderAttributeConstraintHelp();openModal('attribute-modal')}
function renderAttributeConstraintHelp(){const t=byId('attr-type')?.value;const h=byId('attr-constraint-help');if(!h)return;h.textContent=t==='SELECT'||t==='MULTI_SELECT'?'Enter comma-separated allowed values.':t==='NUMBER'||t==='DECIMAL'?'Min and max are numeric constraints.':'Min and max are interpreted as text length constraints.'}
async function saveAttributeFromModal(){try{const type=byId('attr-type').value;const body={name:byId('attr-label').value.trim(),code:byId('attr-code').value.trim(),labelText:byId('attr-label').value.trim(),attributeType:type,required:byId('attr-required').checked,searchable:true,visibleToCustomer:byId('attr-visible').checked,allowedValues:byId('attr-values').value.trim()||null,minLength:null,maxLength:null,minValue:null,maxValue:null};if(['NUMBER','DECIMAL'].includes(type)){body.minValue=byId('attr-min').value||null;body.maxValue=byId('attr-max').value||null}else{body.minLength=byId('attr-min').value?Number(byId('attr-min').value):null;body.maxLength=byId('attr-max').value?Number(byId('attr-max').value):null}await post(`${API}/categories/${byId('attribute-category-id').value}/attributes`,body,{role:'PRODUCT_ADMIN'});toast('Attribute added','success');closeModal('attribute-modal');await refreshAdminConsole();renderAdminCategoryDetail()}catch(e){toast(e.message,'error')}}
function renderCouponCategoryChecks(){const h=byId('coupon-category-checks');if(!h)return;h.innerHTML=state.categories.map(c=>`<label class="check-card"><input type="checkbox" value="${c.id}" data-coupon-cat> ${esc(categoryPath(c.id))}</label>`).join('')}
function setCouponFilter(f,btn){state.admin.couponFilter=f;document.querySelectorAll('#coupon-status-tabs .pill-tab').forEach(b=>b.classList.remove('active'));btn?.classList.add('active');renderAdminCouponList()}
function renderAdminCouponList(){const h=byId('admin-coupon-list');if(!h)return;let rows=state.coupons;const searchVal=byId('admin-coupon-search')?.value?.toLowerCase()||'';if(state.admin.couponFilter!=='ALL')rows=rows.filter(c=>lifecycle(c)===state.admin.couponFilter);if(searchVal)rows=rows.filter(c=>(c.code||'').toLowerCase().includes(searchVal)||(c.description||'').toLowerCase().includes(searchVal));h.innerHTML=rows.length?rows.map(c=>{const status=lifecycle(c);const isPercent=c.discountType==='UPTO_PERCENT_OFF';const discountVal=isPercent?`${Number(c.value)}%`:money(c.value);const discountLabel=isPercent?'UP TO '+money(c.maxDiscountAmount):'FLAT OFF';const stripClass=isPercent?'type-percent':'type-flat';const catNames=(c.eligibleCategoryIds||[]).map(id=>{const cat=categoryById(id);return cat?cat.name:null}).filter(Boolean);return `<article class="admin-coupon-ticket"><div class="coupon-ticket-top"><div class="coupon-discount-strip ${stripClass}"><div class="coupon-discount-value">${discountVal}</div><div class="coupon-discount-label">${discountLabel}</div></div><div class="coupon-ticket-info"><div class="coupon-code-row"><span class="coupon-code-text">${esc(c.code)}</span>${badge(status)}</div><div class="coupon-desc">${esc(c.description||couponText(c))}</div><div class="coupon-ticket-dates"><span class="coupon-date-pill">📅 ${fmtDate(c.startsAt)}</span><span class="coupon-date-pill">⏰ ${fmtDate(c.endsAt)}</span></div></div></div><div class="coupon-ticket-footer"><div class="coupon-ticket-chips"><span class="coupon-chip">${esc(c.discountScope)}</span><span class="coupon-chip">Min ${money(c.minCartAmount)}</span>${catNames.length?`<span class="coupon-chip">📁 ${catNames.length} categor${catNames.length===1?'y':'ies'}</span>`:''}</div><div class="coupon-ticket-actions"><button class="btn-ghost btn-sm" onclick="openCouponModal('${c.id}')">✏️ Edit</button></div></div></article>`}).join(''):empty('No coupons match','Create a coupon or adjust filters.');}
function openCouponModal(id=null){const c=id?state.coupons.find(x=>x.id===id):null;byId('coupon-modal-title').textContent=c?'Edit coupon':'Create coupon';byId('coupon-id').value=c?.id||'';byId('coupon-code').value=c?.code||'';byId('coupon-description').value=c?.description||'';byId('coupon-type').value=c?.discountType||'UPTO_PERCENT_OFF';byId('coupon-value').value=c?.value||'';byId('coupon-max').value=c?.maxDiscountAmount||'';byId('coupon-min-cart').value=c?.minCartAmount||'';byId('coupon-scope').value=c?.discountScope||'CATEGORY';byId('coupon-starts').value=localValue(c?.startsAt||new Date().toISOString());byId('coupon-ends').value=localValue(c?.endsAt||new Date(Date.now()+30*86400000).toISOString());renderCouponCategoryChecks();document.querySelectorAll('[data-coupon-cat]').forEach(input=>input.checked=(c?.eligibleCategoryIds||[]).includes(input.value));renderCouponTypeFields();openModal('coupon-modal')}
function renderCouponTypeFields(){const type=byId('coupon-type')?.value;if(byId('coupon-value-label'))byId('coupon-value-label').textContent=type==='FLAT'?'Flat amount':'Percentage';byId('coupon-max-field')?.classList.toggle('hidden',type==='FLAT')}
async function saveCouponFromModal(){try{const id=byId('coupon-id').value;const categoryIds=[...document.querySelectorAll('[data-coupon-cat]:checked')].map(i=>i.value);const type=byId('coupon-type').value;const body={code:byId('coupon-code').value.trim(),description:byId('coupon-description').value.trim(),discountType:type,discountScope:byId('coupon-scope').value,value:Number(byId('coupon-value').value),maxDiscountAmount:type==='FLAT'?null:Number(byId('coupon-max').value),minCartAmount:byId('coupon-min-cart').value?Number(byId('coupon-min-cart').value):0,status:'ACTIVE',startsAt:toIso(byId('coupon-starts').value),endsAt:toIso(byId('coupon-ends').value),categoryIds};if(id)await put(`${API}/coupons/${id}`,body,{role:'PRODUCT_ADMIN'});else await post(`${API}/coupons`,body,{role:'PRODUCT_ADMIN'});toast('Coupon saved','success');closeModal('coupon-modal');await refreshAdminConsole()}catch(e){toast(e.message,'error')}} 

async function initSellerCenter(){initConsole('SELLER');byId('seller-email')&&(byId('seller-email').textContent=state.user.email);await refreshSellerCenter()}
async function refreshSellerCenter(){try{await Promise.all([loadCategories(),loadCoupons(),loadSellerProfile(),loadSellerProducts(),loadSellerWarehouses(),loadSellerInventory(),loadSellerOrders()]);renderSellerAll()}catch(e){toast(e.message,'error')}}
async function loadSellerProfile(){state.seller.profile=await get(`${API}/sellers/me`,{role:'SELLER'});return state.seller.profile}
async function loadSellerProducts(){state.seller.products=pageContent(await get(`${API}/products?page=0&size=100`,{role:'SELLER'}));return state.seller.products}
async function loadSellerWarehouses(){state.seller.warehouses=pageContent(await get(`${API}/sellers/warehouses?page=0&size=100`,{role:'SELLER'}));return state.seller.warehouses}
async function loadSellerInventory(){state.seller.inventory=await get(`${API}/inventory`,{role:'SELLER'});return state.seller.inventory}
async function loadSellerOrders(){try{state.seller.orders=pageContent(await get(`${API}/sellers/orders?page=0&size=100`,{role:'SELLER'}));renderSellerOrders();return state.seller.orders}catch(e){toast(e.message,'error');return[]}}
function renderSellerAll(){renderSellerProfile();renderSellerStats();renderSellerProducts();renderSellerProductCategorySelect();renderSellerPromotions();renderSellerWarehouses();renderSellerInventory();renderSellerOrders();}
function renderSellerStats(){byId('seller-stat-products').textContent=state.seller.products.length;byId('seller-stat-published').textContent=state.seller.products.filter(p=>p.status==='PUBLISHED').length;byId('seller-stat-warehouses').textContent=state.seller.warehouses.length;byId('seller-stat-orders').textContent=state.seller.orders.filter(o=>!['SHIPPED','CANCELLED','DELIVERED'].includes(o.fulfillmentStatus)).length;const low=state.seller.inventory.filter(i=>i.availableQuantity<=3);byId('seller-low-stock').innerHTML=low.length?low.map(i=>`<div class="offer-card"><span>${productName(i.productId)}</span>${badge(i.availableQuantity===0?'OUT_OF_STOCK':'LOW_STOCK')}</div>`).join(''):empty('No low-stock products','Inventory looks healthy.');byId('seller-recent-orders').innerHTML=state.seller.orders.slice(0,4).map(o=>`<div class="offer-card"><div><strong>${esc(o.orderNumber)}</strong><div class="small muted">${esc(o.productName)} × ${o.quantity}</div></div>${badge(o.fulfillmentStatus)}</div>`).join('')||empty('No order lines','Customer orders will appear here.');}
function renderSellerProfile(){const p=state.seller.profile;byId('seller-business-name')&&(byId('seller-business-name').textContent=p?.businessName||'Seller account');const h=byId('seller-profile-card');if(h)h.innerHTML=`<article class="info-panel"><h2>${esc(p?.businessName||'Seller')}</h2><p class="muted">Email: ${esc(p?.email||state.user.email)}<br>Contact: ${esc(p?.contactNumber||'-')}<br>Seller ID: <span class="kbd">${esc(p?.sellerId||'-')}</span></p></article>`}
function productName(id){return state.seller.products.find(p=>p.id===id)?.name||id}
function warehouseName(id){return state.seller.warehouses.find(w=>w.id===id)?.name||id}
function inventoryForProduct(id){return state.seller.inventory.filter(i=>i.productId===id).reduce((s,i)=>s+i.availableQuantity,0)}
function setProductTab(tab,btn){state.seller.productTab=tab;document.querySelectorAll('#seller-products .pill-tab').forEach(b=>b.classList.remove('active'));btn?.classList.add('active');renderSellerProducts()}
function renderSellerProducts(){const h=byId('seller-product-table');if(!h)return;let rows=state.seller.products;if(state.seller.productTab!=='ALL')rows=rows.filter(p=>p.status===state.seller.productTab);h.innerHTML=rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Coupons</th><th>Actions</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.sku)}</div></td><td>${esc(categoryPath(p.categoryId))}</td><td>${money(p.price)}</td><td>${inventoryForProduct(p.id)}</td><td>${badge(p.status)}</td><td>${state.coupons.filter(c=>c.enrolledProductIds?.includes(p.id)).map(c=>`<span class="chip">${esc(c.code)}</span>`).join('')||'-'}</td><td><div class="inline-actions"><button class="btn-ghost btn-sm" onclick="editSellerProduct('${p.id}')">Edit</button>${p.status==='PUBLISHED'?`<button class="btn-secondary btn-sm" onclick="unpublishProduct('${p.id}')">Unpublish</button>`:`<button class="btn-primary btn-sm" onclick="publishProduct('${p.id}')">Publish</button>`}<button class="btn-danger btn-sm" onclick="deleteSellerProduct('${p.id}')">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No products','Create a category-driven product listing.');renderInventorySelects()}
function renderSellerProductCategorySelect(){const sel=byId('product-category');if(!sel)return;sel.innerHTML='<option value="">Select final category</option>'+state.categories.map(c=>`<option value="${c.id}" ${isLeaf(c.id)?'':'disabled'}>${esc(categoryPath(c.id))}${isLeaf(c.id)?'':' (parent)'}</option>`).join('')}
function renderSellerAttributeFields(){const id=byId('product-category')?.value;const h=byId('seller-dynamic-attributes');if(!h)return;if(!id){h.innerHTML='';return}const c=categoryById(id);const attrs=c?.attributes||[];const required=attrs.filter(a=>a.required), optional=attrs.filter(a=>!a.required);h.innerHTML=`<div class="attr-section-title">Mandatory attributes</div>${required.map(renderProductAttributeInput).join('')||'<p class="small muted">No mandatory attributes.</p>'}<div class="attr-section-title">Optional attributes</div>${optional.map(renderProductAttributeInput).join('')||'<p class="small muted">No optional attributes.</p>'}`}
function renderProductAttributeInput(a){const common=`data-product-attr="${esc(a.code)}" data-attr-type="${a.attributeType}" ${a.required?'required':''}`;let input='';const values=(a.allowedValues||'').split(',').map(v=>v.trim()).filter(Boolean);if(['SELECT','MULTI_SELECT','STRING'].includes(a.attributeType)&&values.length){input=`<select ${common} ${a.attributeType==='MULTI_SELECT'?'multiple':''}>${a.required?'':'<option value="">Optional</option>'}${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`}else if(a.attributeType==='BOOLEAN'){input=`<select ${common}><option value="true">Yes</option><option value="false">No</option></select>`}else if(['NUMBER','DECIMAL'].includes(a.attributeType)){input=`<input type="number" step="${a.attributeType==='DECIMAL'?'0.01':'1'}" ${common}>`}else{input=`<input ${common}>`}return `<div class="form-field"><label>${esc(a.labelText||a.name)} ${a.required?'<span class="muted">*</span>':''}</label>${input}<span class="field-hint">${esc(a.attributeType)} · ${a.visibleToCustomer?'visible to customer':'internal'}</span></div>`}
function collectProductAttributes(){return [...document.querySelectorAll('[data-product-attr]')].map(el=>({code:el.dataset.productAttr,value:Array.from(el.selectedOptions||[]).map(o=>o.value).join(',')||el.value})).filter(a=>a.value!==null&&String(a.value).trim()!=='')}
async function saveSellerProduct(){try{const id=byId('seller-product-id').value;const body={categoryId:byId('product-category').value,name:byId('product-name').value.trim(),description:byId('product-description').value.trim(),sku:byId('product-sku').value.trim(),price:Number(byId('product-price').value),currency:byId('product-currency').value,attributes:collectProductAttributes()};let saved=id?await put(`${API}/products/${id}`,body,{role:'SELLER'}):await post(`${API}/products`,body,{role:'SELLER'});if(byId('product-publish-now').checked&&saved.status!=='PUBLISHED')saved=await patch(`${API}/products/${saved.id}/publish`,{}, {role:'SELLER'});toast('Product saved','success');resetProductForm();await refreshSellerCenter();showConsoleSection('seller-products')}catch(e){toast(e.message,'error')}} 
function resetProductForm(){['seller-product-id','product-name','product-description','product-sku','product-price'].forEach(id=>byId(id)&&(byId(id).value=''));byId('product-category')&&(byId('product-category').value='');byId('product-publish-now')&&(byId('product-publish-now').checked=false);renderSellerAttributeFields();byId('product-form-title')&&(byId('product-form-title').textContent='Create product')}
function editSellerProduct(id){const p=state.seller.products.find(x=>x.id===id);if(!p)return;showConsoleSection('seller-new-product');byId('product-form-title').textContent='Edit product';byId('seller-product-id').value=p.id;byId('product-name').value=p.name;byId('product-description').value=p.description||'';byId('product-sku').value=p.sku;byId('product-price').value=p.price;byId('product-category').value=p.categoryId;renderSellerAttributeFields();(p.attributes||[]).forEach(a=>{const el=document.querySelector(`[data-product-attr="${a.code}"]`);if(el)el.value=a.value})}
async function publishProduct(id){try{await patch(`${API}/products/${id}/publish`,{}, {role:'SELLER'});toast('Product published','success');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
async function unpublishProduct(id){try{await patch(`${API}/products/${id}/unpublish`,{}, {role:'SELLER'});toast('Product unpublished','success');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
async function deleteSellerProduct(id){if(!confirm('Delete this product?'))return;try{await del(`${API}/products/${id}`,{role:'SELLER'});toast('Product deleted','success');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
function renderSellerPromotions(){const h=byId('seller-promotion-list');if(!h)return;if(!state.coupons.length){h.innerHTML=empty('No coupons available','Product Admin can create promotions for sellers to enroll.');return}h.innerHTML=state.coupons.map(c=>{const status=lifecycle(c);const eligible=state.seller.products.filter(p=>couponEligibleForCategory(c,p.categoryId));const enrolled=eligible.filter(p=>c.enrolledProductIds?.includes(p.id)).length;const percent=eligible.length?Math.round((enrolled/eligible.length)*100):0;const discountDisplay=c.discountType==='FLAT'?`<span class="promo-amount">${money(c.value)}</span><span class="promo-type">FLAT OFF</span>`:`<span class="promo-amount">${Number(c.value)}%</span><span class="promo-type">up to ${money(c.maxDiscountAmount)}</span>`;return `<article class="promo-card"><div class="promo-card-header"><h3>${esc(c.code)}</h3>${badge(status)}</div><div class="promo-card-discount">${discountDisplay}</div><p class="small muted">${esc(c.description||couponText(c))}</p><div class="promo-card-bar"><div class="promo-bar-label"><span>Enrollment</span><span class="enrolled-count">${enrolled} / ${eligible.length} products</span></div><div class="promo-bar-track"><div class="promo-bar-fill" style="width:${percent}%"></div></div></div><div class="promo-card-dates"><span class="date-item">📅 Live: ${fmtDate(c.startsAt)}</span><span class="date-item">⏰ Expires: ${fmtDate(c.endsAt)}</span></div>${c.minCartAmount>0?`<div class="chip-row" style="margin-top:8px"><span class="chip">Min cart ${money(c.minCartAmount)}</span>${c.eligibleCategoryIds?.length?`<span class="chip">${c.eligibleCategoryIds.length} categories</span>`:''}</div>`:''}<div style="margin-top:14px"><button class="btn-primary btn-sm" onclick="openPromotionModal('${esc(c.code)}')" ${status==='EXPIRED'||status==='INACTIVE'?'disabled':''}>Manage enrollment</button></div></article>`}).join('')}
function couponEligibleForCategory(coupon,catId){const ids=coupon.eligibleCategoryIds||[];return !ids.length||ancestorsOf(catId).some(id=>ids.includes(id))}
function openPromotionModal(code){const c=state.coupons.find(x=>x.code===code);byId('promotion-code').value=code;byId('promotion-modal-title').textContent=`Enroll products into ${code}`;const eligible=state.seller.products.filter(p=>couponEligibleForCategory(c,p.categoryId));byId('promotion-products').innerHTML=eligible.length?eligible.map(p=>`<label class="check-card"><input type="checkbox" value="${p.id}" data-promo-product ${c.enrolledProductIds?.includes(p.id)?'checked':''}> ${esc(p.name)} <span class="muted small">${esc(categoryPath(p.categoryId))}</span></label>`).join(''):empty('No eligible products','Only seller-owned products in eligible categories appear here.');openModal('promotion-modal')}
async function savePromotionEnrollment(){try{const code=byId('promotion-code').value;const c=state.coupons.find(x=>x.code===code);for(const input of document.querySelectorAll('[data-promo-product]')){const enrolled=c.enrolledProductIds?.includes(input.value);if(input.checked&&!enrolled)await post(`${API}/coupons/${code}/products/${input.value}/enroll`,{}, {role:'SELLER'});if(!input.checked&&enrolled)await del(`${API}/coupons/${code}/products/${input.value}/enroll`,{role:'SELLER'});}toast('Enrollment updated','success');closeModal('promotion-modal');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
function renderSellerWarehouses(){const h=byId('seller-warehouse-list');if(!h)return;h.innerHTML=state.seller.warehouses.map(w=>`<article class="management-card"><h3>${esc(w.name)}</h3><p class="small muted">${esc(w.code)}<br>${esc(w.addressLine1)}, ${esc(w.city)}, ${esc(w.state)} ${esc(w.postalCode)}</p><div class="inline-actions"><button class="btn-primary btn-sm" onclick="openWarehouseModal('${w.id}')">Edit</button><button class="btn-danger btn-sm" onclick="deleteWarehouse('${w.id}')">Delete</button></div></article>`).join('')||empty('No warehouses','Create a warehouse before updating inventory.');renderInventorySelects()}
function openWarehouseModal(id=null){const w=id?state.seller.warehouses.find(x=>x.id===id):null;byId('warehouse-modal-title').textContent=w?'Edit warehouse':'Create warehouse';byId('warehouse-id').value=w?.id||'';byId('warehouse-name').value=w?.name||'';byId('warehouse-code').value=w?.code||'';byId('warehouse-code').disabled=!!w;byId('warehouse-address').value=w?.addressLine1||'';byId('warehouse-city').value=w?.city||'';byId('warehouse-state').value=w?.state||'';byId('warehouse-country').value=w?.country||'India';byId('warehouse-postal').value=w?.postalCode||'';openModal('warehouse-modal')}
async function saveWarehouseFromModal(){try{const id=byId('warehouse-id').value;const body={name:byId('warehouse-name').value.trim(),code:byId('warehouse-code').value.trim(),addressLine1:byId('warehouse-address').value.trim(),city:byId('warehouse-city').value.trim(),state:byId('warehouse-state').value.trim(),country:byId('warehouse-country').value.trim(),postalCode:byId('warehouse-postal').value.trim(),status:'ACTIVE'};if(id)await put(`${API}/sellers/warehouses/${id}`,body,{role:'SELLER'});else await post(`${API}/sellers/warehouses`,body,{role:'SELLER'});toast('Warehouse saved','success');closeModal('warehouse-modal');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
async function deleteWarehouse(id){if(!confirm('Delete this warehouse? Warehouses with inventory cannot be deleted.'))return;try{await del(`${API}/sellers/warehouses/${id}`,{role:'SELLER'});toast('Warehouse deleted','success');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
function renderInventorySelects(){const ps=byId('inventory-product'), ws=byId('inventory-warehouse');if(ps)ps.innerHTML=state.seller.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');if(ws)ws.innerHTML=state.seller.warehouses.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}
function toggleNewInventoryRow(){const row=byId('seller-inventory-new-row');if(row)row.classList.toggle('hidden');renderInventorySelects()}
function renderSellerInventory(){renderInventorySelects();const h=byId('seller-inventory-table');if(!h)return;h.innerHTML=state.seller.inventory.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Warehouse</th><th>Available</th><th>Reserved</th><th>Status</th><th style="width:140px">Actions</th></tr></thead><tbody>${state.seller.inventory.map(i=>`<tr><td><strong>${esc(productName(i.productId))}</strong></td><td>${esc(warehouseName(i.warehouseId))}</td><td><input type="number" min="0" id="inv-qty-${i.productId}-${i.warehouseId}" value="${i.availableQuantity}" style="width:80px;padding:6px 10px;font-weight:700;border-radius:8px;text-align:center"></td><td>${i.reservedQuantity}</td><td>${badge(i.availableQuantity>0?'IN_STOCK':'OUT_OF_STOCK')}</td><td><button class="btn-primary btn-sm" onclick="saveInlineInventory('${i.productId}','${i.warehouseId}')">💾 Save</button></td></tr>`).join('')}</tbody></table></div>`:empty('No inventory rows','Click "Add stock entry" above to set stock for a product and warehouse.');}
async function saveInlineInventory(productId,warehouseId){try{const qty=Number(byId(`inv-qty-${productId}-${warehouseId}`).value);await put(`${API}/inventory`,{productId,warehouseId,availableQuantity:qty,reason:'STOCK_CORRECTION'},{role:'SELLER'});toast('Inventory updated','success');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
async function saveInventoryUpdate(){try{await put(`${API}/inventory`,{productId:byId('inventory-product').value,warehouseId:byId('inventory-warehouse').value,availableQuantity:Number(byId('inventory-qty').value),reason:'STOCK_CORRECTION'},{role:'SELLER'});toast('Inventory updated','success');toggleNewInventoryRow();await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
function setOrderTab(tab,btn){state.seller.orderTab=tab;document.querySelectorAll('#seller-order-tabs .pill-tab').forEach(b=>b.classList.remove('active'));btn?.classList.add('active');renderSellerOrders()}
function renderSellerOrders(){const h=byId('seller-orders-table');if(!h)return;let rows=state.seller.orders;if(state.seller.orderTab==='PENDING')rows=rows.filter(o=>['PENDING','RESERVED'].includes(o.fulfillmentStatus));else if(state.seller.orderTab==='SHIPPED')rows=rows.filter(o=>o.fulfillmentStatus==='SHIPPED');else if(state.seller.orderTab==='CANCELLED')rows=rows.filter(o=>o.fulfillmentStatus==='CANCELLED');h.innerHTML=rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Qty</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.orderNumber)}</strong><div class="small muted">${fmtDate(o.createdAt)}</div></td><td>${esc(o.customerName)}<div class="small muted">${esc(o.shippingAddress||'-')}</div></td><td>${esc(o.productName)}</td><td>${o.quantity}</td><td>${money(o.totalAmount)}</td><td>${badge(o.fulfillmentStatus)}</td><td><div class="inline-actions"><button class="btn-success btn-sm" onclick="shipOrderLine('${o.lineId}')" ${!['PENDING','RESERVED'].includes(o.fulfillmentStatus)?'disabled':''}>Ship</button><button class="btn-danger btn-sm" onclick="cancelOrderLine('${o.lineId}')" ${o.fulfillmentStatus==='SHIPPED'||o.fulfillmentStatus==='DELIVERED'||o.fulfillmentStatus==='CANCELLED'?'disabled':''}>Cancel</button></div></td></tr>`).join('')}</tbody></table></div>`:empty(state.seller.orderTab==='ALL'?'No seller order lines':'No orders in this status',state.seller.orderTab==='ALL'?'Customer orders containing your products appear here.':'Try a different filter.');}
async function shipOrderLine(id){try{await patch(`${API}/sellers/orders/lines/${id}/ship`,{}, {role:'SELLER'});toast('Order line shipped','success');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}
async function cancelOrderLine(id){if(!confirm('Cancel this order line and restock inventory?'))return;try{await patch(`${API}/sellers/orders/lines/${id}/cancel`,{}, {role:'SELLER'});toast('Order line cancelled','success');await refreshSellerCenter()}catch(e){toast(e.message,'error')}}

function filterAdminCategoryTree(query){const nodes=document.querySelectorAll('#admin-category-tree .admin-node');const q=query.toLowerCase();nodes.forEach(n=>{const name=n.querySelector('.node-name')?.textContent?.toLowerCase()||'';n.style.display=(!q||name.includes(q))?'':'none'})}
function filterAdminCoupons(){renderAdminCouponList()}



